import {seedView,seedCounts,seedReplacement,startSeed,chooseSeedPrediction,drawSeed,repeatSeed,resumeSeed,recoverSeed,browserSeedSlot} from './seed-stall-core.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let turn={state:null,count:3,choosing:false,pending:null,notice:''};
export function resetSeedTurn(){turn={state:null,count:3,choosing:false,pending:null,notice:''};}
function activeTurn(state){if(turn.state!==state)turn={state,count:3,choosing:false,pending:null,notice:''};return turn;}
const button=(label,attribute,primary=false,disabled=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attribute} ${disabled?'disabled':''}>${esc(label)}</button>`;
const count=x=>x.source.slots.filter(s=>s==='sun').length;
const status=()=>`<p class="seed-status" id="seed-status" role="status" tabindex="-1">${esc(turn.notice)}</p>`;
function bag(slots,labels){
 const sun=slots.filter(x=>x==='sun').length,moon=6-sun;
 return `<div class="seed-bag" role="img" aria-label="Six pictured seed counters: ${sun} ${esc(labels.sun)} and ${moon} ${esc(labels.moon)}. Each position is available for every screen draw."><div class="seed-bag-marks" aria-hidden="true">${slots.map((mark,i)=>`<span class="seed-counter seed-${mark}" data-seed-counter data-mark="${mark}" data-slot="${i}">${mark==='sun'?'☼':'☾'}</span>`).join('')}</div></div><p class="seed-counts">Your bag has <strong>${sun}</strong> ${esc(labels.sun.toLowerCase())} seeds and <strong>${moon}</strong> ${esc(labels.moon.toLowerCase())} seeds.</p>`;
}
function chart(run,source){
 const counts=seedCounts(run.draws);
 return `<div class="seed-results"><ol class="seed-draw-list" aria-label="Ordered screen draws">${Array.from({length:6},(_,i)=>`<li data-seed-result="${i+1}">${i<run.draws.length?`<span data-seed-drawn="${run.draws[i]}">${esc(source.labels[run.draws[i]])}</span>`:'Not drawn'}</li>`).join('')}</ol><div class="seed-chart" role="img" aria-label="This run so far: ${counts.sun} ${esc(source.labels.sun)} and ${counts.moon} ${esc(source.labels.moon)}, on a zero to six count scale.">${['sun','moon'].map(mark=>`<div class="seed-chart-row"><span>${esc(source.labels[mark])}</span><div class="seed-track"><span class="seed-bar seed-${mark}" data-seed-bar="${mark}" data-value="${counts[mark]}" style="width:${counts[mark]/6*100}%"></span></div><strong>${counts[mark]}</strong></div>`).join('')}<div class="seed-ticks" aria-hidden="true">${Array.from({length:7},(_,i)=>`<span>${i}</span>`).join('')}</div></div><p class="tiny">Bars begin at 0 and count this run's recorded screen draws. A blank place has not been drawn yet.</p></div>`;
}
function runSummary(run,source,index){const c=seedCounts(run.draws);return `<tr><th scope="row">Run ${index+1}</th><td>${c.sun}</td><td>${c.moon}</td><td>${esc(source.predictionLabels[run.prediction??'none'])}</td></tr>`;}
function history(view){
 if(!view.readable.length&&!view.unreadable.length)return '';
 return `<details class="seed-history"><summary>Saved Seed Stall experiments (${view.readable.length} readable)</summary><p>These are virtual screen draws, not physical samples or grades.</p>${view.readable.map(({entry})=>{const sun=count(entry),moon=6-sun;return `<article><h3>Experiment ${entry.id}: ${sun} ${esc(entry.source.labels.sun)}, ${moon} ${esc(entry.source.labels.moon)}</h3><p>${esc(entry.source.rule)}</p>${button('Return to experiment '+entry.id,`data-seed-resume="${entry.id}"`,false,view.root.current===entry.id)}<table><caption>Saved runs with this bag</caption><thead><tr><th>Run</th><th>${esc(entry.source.labels.sun)}</th><th>${esc(entry.source.labels.moon)}</th><th>Prediction</th></tr></thead><tbody>${entry.runs.map((run,i)=>runSummary(run,entry.source,i)).join('')}</tbody></table><p class="tiny">${entry.runs.at(-1).draws.length} of 6 draws recorded in the latest run.</p></article>`;}).join('')}${view.unreadable.length?`<p>${view.unreadable.length} earlier entry or entries cannot be shown safely. Their original data remains in the notes download.</p>`:''}</details>`;
}
function chooser(view){
 const slots=[...Array(turn.count).fill('sun'),...Array(6-turn.count).fill('moon')];
 const replacement=seedReplacement(view),pending=turn.pending===replacement?.entry.id&&replacement!==null;
 return `<section class="seed-panel"><h2>Choose your bag</h2><p>These are make-believe seed counters. Choose how many of the six have a sun mark.</p>${bag(slots,{sun:'Sun',moon:'Moon'})}<div class="seed-adjust">${button('One fewer sun seed','data-seed-adjust="-1"',false,turn.count===0)}<strong>${turn.count} sun, ${6-turn.count} moon</strong>${button('One more sun seed','data-seed-adjust="1"',false,turn.count===6)}</div><p class="seed-rule">This is a screen draw. Each of the six pictured seeds has the same chance each time. We return the seed before the next draw.</p>${pending?`<section class="seed-confirm" aria-label="Confirm replacing one saved experiment"><p>Starting a new bag will replace <strong>experiment ${replacement.entry.id}</strong> (${count(replacement.entry)} sun, ${6-count(replacement.entry)} moon), the first readable experiment in your saved list. ${replacement.entry.runs.at(-1).draws.length<6?'Its latest run is unfinished.':'Its latest run is complete.'} The other experiments stay here.</p>${button('Download notes first','data-seed-download')}${button('Keep earlier work','data-seed-cancel')}${button('Replace this one and start','data-seed-confirm',true)}</section>`:button('Start with this bag','data-seed-start',true)}${view.status==='ready'&&view.current?button('Back to the current bag','data-seed-cancel'):''}</section>`;
}
function active(entry){
 const source=entry.source,run=entry.runs.at(-1),n=run.draws.length,counts=seedCounts(run.draws),past=entry.runs.filter(r=>r.draws.length===6),sunInBag=count(entry);
 const prediction=run.prediction===null?'none':run.prediction;
 return `<section class="seed-panel"><p class="tiny">Experiment ${entry.id} · run ${entry.runs.length} of 3</p><h2 id="seed-run-heading" tabindex="-1">Draw from your bag</h2>${bag(source.slots,source.labels)}<p class="seed-rule">${esc(source.rule)}</p><p>${esc(source.explanation)}</p>${n?`<p class="seed-recorded-prediction">${run.prediction===null?'No prediction was recorded before this run’s first draw.':`Prediction before this run: ${esc(source.predictionLabels[run.prediction])}.`}</p>`:`<fieldset class="seed-prediction"><legend>${esc(source.predictionPrompt)}</legend><div class="seed-choices">${['sun','moon','same','unsure','none'].map(key=>button(source.predictionLabels[key],`data-seed-predict="${key}" aria-pressed="${prediction===key}"`)).join('')}</div></fieldset><p class="tiny">Prediction is optional and unscored. You can change it until the first draw.</p>`}${n<6?button(`Draw seed ${n+1} of 6`,'data-seed-draw',true):''}${n?`<p class="seed-returned">${esc(source.labels[run.draws.at(-1)])} appeared. Returned to the bag. All six seeds can be drawn next.</p>`:''}${chart(run,source)}${n===6?`<section class="seed-finish" id="seed-finish" tabindex="-1"><h3>This run is recorded</h3><p>This run showed ${counts.sun} ${esc(source.labels.sun.toLowerCase())} and ${counts.moon} ${esc(source.labels.moon.toLowerCase())}. Prediction: ${esc(source.predictionLabels[prediction])}.</p><p>${sunInBag===0||sunInBag===6?`This bag can show only ${esc(source.labels[source.slots[0]].toLowerCase())}, because every pictured seed has that mark.`:sunInBag===3?'Both marks have the same chance on each draw. Six draws need not end in a tie.':'A bag with more of one mark makes that mark more likely on each draw. One short run can look different.'} These counts do not test a real bag or prove fairness.</p>${entry.runs.length<3?button('Try another six draws with this bag','data-seed-repeat',true):'<p>All three short runs with this bag are recorded.</p>'}</section>`:''}${past.length?`<table class="seed-run-table"><caption>Runs with this frozen bag</caption><thead><tr><th>Run</th><th>${esc(source.labels.sun)}</th><th>${esc(source.labels.moon)}</th><th>Prediction</th></tr></thead><tbody>${past.map((r,i)=>runSummary(r,source,i)).join('')}</tbody></table>`:''}<details class="seed-talk"><summary>Talk together</summary><p>Which mark was more likely from the bag? Did every short run have to follow that pattern? Returning a seed leaves the next draw's chances unchanged.</p></details>${button('Change the bag for a new experiment','data-seed-change')}</section>`;
}
export const seedEntry=()=>'<section class="resume-strip seed-entry"><div><h2>Seed Stall</h2><p>Choose a pictured bag, predict, and compare short screen-draw runs.</p><a class="secondary" href="#numbers/seeds">Try the Seed Stall</a></div></section>';
export function seedPage(state){
 activeTurn(state);const v=seedView(state),showChooser=v.status==='missing'||v.status==='ready'&&(!v.current||turn.choosing);
 return `<div class="seed-sheet" data-seed-root><a class="back" href="#numbers">← Back to Number Garden</a><h1 id="seed-title" tabindex="-1">Seed Stall</h1><p>Make-believe screen draws. Choose a bag, then see what happens. One short run cannot prove a bag is fair.</p>${status()}${v.status==='recovery'?`<section class="seed-panel"><h2>Earlier Seed Stall record</h2><p>This record cannot be opened safely. It stays unchanged in your notes download. You can start a separate Seed Stall while keeping the earlier data.</p>${button('Use a new Seed Stall','data-seed-recover',true)}</section>`:showChooser?chooser(v):active(v.current)}${v.status==='ready'?history(v):''}<p class="seed-links"><a class="secondary" href="#notes">Grown-up notes</a><a class="secondary" href="#numbers">Number Garden</a></p></div>`;
}
export function seedNotes(state){
 if(!Object.hasOwn(state,'seedStall'))return '';
 const v=seedView(state);return `<details class="panel seed-notes"><summary>Seed Stall: virtual screen draws</summary><p>Bag sources, optional predictions and each virtual outcome are kept separately. Short runs are not physical measurements, a fairness proof, or an attainment judgment. Unreadable original data remains in this download.</p><p>${v.status==='ready'?`${v.readable.length} readable experiment(s), ${v.unreadable.length} unavailable entry or entries.`:'Earlier Seed Stall format unavailable here.'}</p><pre>${esc(JSON.stringify(state.seedStall,null,2))}</pre></details>`;
}
export function bindSeed(state,{save,render,focus,canExport,downloadNotes,randomSlot=browserSeedSlot}){
 if(!document.querySelector('[data-seed-root]'))return;
 const redraw=selector=>{render();focus(selector);};
 const refuse=(message,selector)=>{turn.notice=message||'That change cannot fit safely in a notes download. Your earlier work is still here.';redraw(selector);};
 document.querySelectorAll('[data-seed-adjust]').forEach(b=>b.onclick=()=>{turn.count+=Number(b.dataset.seedAdjust);turn.pending=null;turn.notice='';render();focus(`[data-seed-adjust="${b.dataset.seedAdjust}"]:not(:disabled), #seed-title`);});
 document.querySelector('[data-seed-change]')?.addEventListener('click',()=>{const v=seedView(state);turn.count=v.current?count(v.current):3;turn.choosing=true;turn.pending=null;turn.notice='';redraw('#seed-title');});
 document.querySelectorAll('[data-seed-cancel]').forEach(b=>b.onclick=()=>{turn.pending=null;turn.choosing=false;turn.notice='';redraw('#seed-title');});
 const start=()=>{const v=seedView(state),old=seedReplacement(v);if(old&&turn.pending!==old.entry.id){turn.pending=old.entry.id;turn.notice='Choose whether to download notes or replace the named experiment.';redraw('#seed-status');return;}const result=startSeed(state,turn.count,old?.entry.id??null,canExport);if(!result){refuse(null,old?'[data-seed-confirm]':'[data-seed-start]');return;}turn.choosing=false;turn.pending=null;turn.notice='';save();redraw('#seed-run-heading');};
 document.querySelector('[data-seed-start]')?.addEventListener('click',start);
 document.querySelector('[data-seed-confirm]')?.addEventListener('click',start);
 document.querySelector('[data-seed-download]')?.addEventListener('click',()=>{downloadNotes();turn.notice='Notes download started. Confirm replacement only if you are ready.';redraw('#seed-status');});
 document.querySelector('[data-seed-recover]')?.addEventListener('click',()=>{if(!recoverSeed(state,canExport)){refuse(null,'[data-seed-recover]');return;}turn.notice='The earlier record stays in your notes. Choose a new bag when ready.';save();redraw('#seed-title');});
 document.querySelectorAll('[data-seed-predict]').forEach(b=>b.onclick=()=>{const choice=b.dataset.seedPredict==='none'?null:b.dataset.seedPredict;if(!chooseSeedPrediction(state,choice,canExport)){refuse(null,`[data-seed-predict="${b.dataset.seedPredict}"]`);return;}turn.notice='';save();redraw(`[data-seed-predict="${b.dataset.seedPredict}"]`);});
 document.querySelector('[data-seed-draw]')?.addEventListener('click',()=>{const slot=randomSlot();if(slot===null){refuse('This browser could not make a screen draw. Your bag and earlier results are still here.','[data-seed-draw]');return;}if(!drawSeed(state,slot,canExport)){refuse(null,'[data-seed-draw]');return;}turn.notice='';save();const n=seedView(state).current.runs.at(-1).draws.length;redraw(n===6?'#seed-finish':'[data-seed-draw]');});
 document.querySelector('[data-seed-repeat]')?.addEventListener('click',()=>{if(!repeatSeed(state,canExport)){refuse(null,'[data-seed-repeat]');return;}turn.notice='';save();redraw('#seed-run-heading');});
 document.querySelectorAll('[data-seed-resume]').forEach(b=>b.onclick=()=>{if(!resumeSeed(state,Number(b.dataset.seedResume),canExport)){refuse(null,`[data-seed-resume="${b.dataset.seedResume}"]`);return;}turn.choosing=false;turn.pending=null;turn.notice='';save();redraw('#seed-run-heading');});
}
